python3 - <<'PY'
p='deploy/nginx.conf'
s=open(p).read()
s=s.replace("""'}';

server {""","""'}';

# Astro's hashed build assets never change -> cache forever.
# Everything else (HTML, RSS) revalidates so new posts show up immediately.
map $uri $cache_control {
    ~^/_astro/  "public, max-age=31536000, immutable";
    default     "no-cache";
}

server {""")
start=s.index("    # Astro's hashed build assets never change -> cache forever.\n    location /_astro/")
end=s.index("    error_page 404")
s=s[:start]+"""    location / {
        try_files $uri $uri/index.html $uri/ =404;
    }

"""+s[end:]
s=s.replace("""    add_header Strict-Transport-Security""","""    # Note: these only apply because no location block sets its own add_header.
    add_header Cache-Control $cache_control always;
    add_header Strict-Transport-Security""",1)
open(p,'w').write(s)
PY
